WITH dupes AS (
  SELECT u.id AS dup_id
  FROM users u
  WHERE EXISTS (
    SELECT 1 FROM users k WHERE lower(k.email) = lower(u.email) AND k.id != u.id
  )
  AND u.id != (SELECT k.id FROM users k WHERE lower(k.email) = lower(u.email) ORDER BY k.created_at, k.id LIMIT 1)
)
DELETE FROM users
WHERE id IN (SELECT dup_id FROM dupes);

